use tracing :: trace ; use tide :: Request ; use tide :: prelude :: * ; use common :: Rpc ; # [async_std :: main] async fn main () -> tide :: Result < () > { let mut app = tide :: new () ; app . at ("/api") . post (api) ; app . listen ("127.0.0.1:8080") . await ? ; Ok (()) } async fn api (mut req : Request < () >) -> tide :: Result { let body = req . body_bytes () . await ? ; let rpc : Rpc = rmp_serde :: from_read_ref (& body) ? ; trace ! ("rpc: {:?}" , rpc) ; Ok (format ! ("rpc: {:?}" , rpc) . into ()) }